void Solver::bump_var(int var, double coeff) {
    // increase activity by a scaled increment
    double delta = var_inc * coeff;
    activity[var] += delta;

    // if any activity becomes excessively large, rescale all activities
    const double RESCALE_LIMIT = 1e150;
    if (activity[var] > RESCALE_LIMIT) {
        double scale = 1e-150;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= scale;
        }
        var_inc *= scale;
    }

    // keep the VSIDS priority queue up‑to‑date
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
